package com.railflow.yardops.exception;
import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.server.ResponseStatusException; import java.time.Instant; import java.util.Map;
@RestControllerAdvice public class GlobalExceptionHandler { @ExceptionHandler(ResponseStatusException.class) ResponseEntity<Map<String,Object>> status(ResponseStatusException ex){return ResponseEntity.status(ex.getStatusCode()).body(Map.of("timestamp",Instant.now(),"status",ex.getStatusCode().value(),"error",ex.getReason()==null?"Request failed":ex.getReason()));} @ExceptionHandler(Exception.class) ResponseEntity<Map<String,Object>> general(Exception ex){return ResponseEntity.status(HttpStatus.INTERNAL_SERVER_ERROR).body(Map.of("timestamp",Instant.now(),"status",500,"error","Unexpected server error"));} }